FUNCTION handleCreateTable(request):
    // REQ-4-013; preconditions: JSON and persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE REQ-4-002 OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF code exists THEN ROLLBACK; RETURN 409. END IF CREATE table; COMMIT; RETURN 201 with Location.
    // Non-idempotent; rollback preserves all tables and reservation relations.

FUNCTION handlePatchTable(request, table_id):
    // REQ-4-015; preconditions: existing table, JSON, persistence available.
    REQUIRE admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE partial result OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock table and active reservations; IF capacity would be below active or confirmed demand, duplicate code, or invalid deactivation THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Identical payload idempotent; rollback preserves all relations.

FUNCTION handleDeleteTable(request, table_id):
    // REQ-4-016; preconditions: existing table and persistence available.
    REQUIRE admin OR RETURN 401 or 403; RETURN 404 for invalid or absent id. BEGIN TRANSACTION; IF any reservation references table THEN ROLLBACK; RETURN 409. END IF MARK deleted; COMMIT; RETURN 204.
    // REQ-4-009; repeat is 404 and rollback leaves all reservation relations unchanged.

FUNCTION handleCreateReservation(request):
    // REQ-4-018; preconditions: JSON, active table, persistence available.
    REQUIRE user or admin OR RETURN 401; REQUIRE JSON OR RETURN 415; VALIDATE REQ-4-003 OR RETURN 400 or 422; missing table is 404.
    BEGIN TRANSACTION; lock table and overlap set; IF active demand violates REQ-4-004 THEN ROLLBACK; RETURN 409. END IF CREATE PENDING owner caller; COMMIT; RETURN 201 with Location.
    // REQ-4-007: non-idempotent, rollback preserves capacity and relations.

FUNCTION handlePatchReservation(request, reservation_id):
    // REQ-4-020; preconditions: JSON, existing reservation, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415. BEGIN TRANSACTION; IF status is not PENDING THEN ROLLBACK; RETURN 409. END IF
    VALIDATE result OR ROLLBACK; RETURN 400 or 422; lock target interval; IF missing table THEN ROLLBACK; RETURN 404; IF active demand exceeds limit THEN ROLLBACK; RETURN 409. END IF UPDATE; COMMIT; RETURN 200.
    // Idempotent identical payload; rollback preserves reservation and capacity state.

FUNCTION handleConfirmReservation(request, reservation_id):
    // REQ-4-021; preconditions: JSON, existing PENDING reservation, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE timestamp OR RETURN 400 or 422.
    BEGIN TRANSACTION; lock table and overlap set; IF status not PENDING or confirmed demand exceeds seats THEN ROLLBACK; RETURN 409. END IF SET CONFIRMED; COMMIT; RETURN 200.
    // REQ-4-005 and REQ-4-007; non-idempotent and rollback preserves demand.

FUNCTION handleCancelReservation(request, reservation_id):
    // REQ-4-022; preconditions: JSON, existing reservation, persistence available.
    REQUIRE creator or admin OR RETURN 401 or 403; REQUIRE JSON OR RETURN 415; VALIDATE cancellation fields OR RETURN 400 or 422.
    BEGIN TRANSACTION; IF terminal status THEN ROLLBACK; RETURN 409. END IF SET CANCELLED and immutable history; COMMIT; RETURN 200.
    // REQ-4-006 and REQ-4-007; non-idempotent, rollback leaves capacity and relations unchanged.

FUNCTION handleNoShowReservation(request, reservation_id):
